// Work out every outside place each workflow sends data to. Nothing is guessed: anything the
// workflow itself does not state is kept as "unresolved", and unresolved goes to review.
// A live workflow is judged on its PUBLISHED version (activeVersion), because that is what runs.
const selfId = $workflow.id;

// Node types that keep data inside n8n, or only move it from node to node.
const LOCAL = new Set([
  'code', 'set', 'if', 'switch', 'merge', 'filter', 'splitInBatches', 'splitOut', 'aggregate',
  'noOp', 'wait', 'stopAndError', 'sort', 'limit', 'summarize', 'removeDuplicates',
  'compareDatasets', 'renameKeys', 'itemLists', 'dateTime', 'crypto', 'xml', 'html', 'markdown',
  'extractFromFile', 'convertToFile', 'spreadsheetFile', 'readWriteFile', 'readBinaryFile',
  'readBinaryFiles', 'writeBinaryFile', 'moveBinaryData', 'editImage', 'compression', 'totp',
  'jwt', 'function', 'functionItem', 'executionData', 'debugHelper', 'stickyNote', 'n8n',
  'n8nTrigger', 'workflowTrigger', 'errorTrigger', 'manualTrigger', 'scheduleTrigger', 'cron',
  'interval', 'executeWorkflowTrigger', 'webhook', 'respondToWebhook', 'form', 'formTrigger',
  'chatTrigger', 'manualChatTrigger', 'chat', 'dataTable', 'dataTableTool', 'localFileTrigger',
  'evaluation', 'evaluationTrigger', 'rssFeedRead', 'rssFeedReadTrigger',
  'agent', 'agentTool', 'chainLlm', 'chainSummarization', 'chainRetrievalQa',
  'informationExtractor', 'textClassifier', 'sentimentAnalysis', 'outputParserStructured',
  'outputParserAutofixing', 'outputParserItemList',
  'documentDefaultDataLoader',
  'documentBinaryInputLoader', 'documentJsonInputLoader', 'memoryBufferWindow', 'memoryManager',
  'toolCode', 'toolCalculator', 'toolThink', 'vectorStoreInMemory', 'vectorStoreInMemoryInsert',
  'vectorStoreInMemoryLoad', 'retrieverVectorStore', 'retrieverMultiQuery',
  'retrieverContextualCompression', 'modelSelector',
]);

// The company behind a node type. Anything not listed is named after its node type, so a
// service this list has never heard of still shows up - it is never treated as local.
const VENDOR = {
  gmail: 'Google', googleSheets: 'Google', googleDrive: 'Google', googleDocs: 'Google',
  googleCalendar: 'Google', googleBigQuery: 'Google', googleCloudStorage: 'Google',
  googleContacts: 'Google', googleTasks: 'Google', googleSlides: 'Google', googleTranslate: 'Google',
  googleAnalytics: 'Google', googleChat: 'Google', googleFirebaseCloudFirestore: 'Google',
  googleFirebaseRealtimeDatabase: 'Google', youTube: 'Google', gSuiteAdmin: 'Google',
  googleGemini: 'Google', lmChatGoogleGemini: 'Google', lmChatGoogleVertex: 'Google',
  embeddingsGoogleGemini: 'Google', embeddingsGoogleVertex: 'Google', lmGooglePalm: 'Google',
  openAi: 'OpenAI', lmChatOpenAi: 'OpenAI', lmOpenAi: 'OpenAI', embeddingsOpenAi: 'OpenAI',
  openAiAssistant: 'OpenAI', anthropic: 'Anthropic', lmChatAnthropic: 'Anthropic',
  lmChatGroq: 'Groq', groq: 'Groq', lmChatMistralCloud: 'Mistral AI', embeddingsMistralCloud: 'Mistral AI',
  mistralAi: 'Mistral AI', lmChatDeepSeek: 'DeepSeek', lmChatOpenRouter: 'OpenRouter',
  lmChatXAiGrok: 'xAI', lmChatCohere: 'Cohere', embeddingsCohere: 'Cohere', rerankerCohere: 'Cohere',
  lmChatAzureOpenAi: 'Microsoft', embeddingsAzureOpenAi: 'Microsoft', microsoftOutlook: 'Microsoft',
  microsoftTeams: 'Microsoft', microsoftExcel: 'Microsoft', microsoftOneDrive: 'Microsoft',
  microsoftToDo: 'Microsoft', microsoftEntra: 'Microsoft', microsoftSharePoint: 'Microsoft',
  azureCosmosDb: 'Microsoft', azureStorage: 'Microsoft', microsoftSql: 'Microsoft SQL database',
  lmChatAwsBedrock: 'Amazon Web Services', embeddingsAwsBedrock: 'Amazon Web Services',
  awsS3: 'Amazon Web Services', awsSes: 'Amazon Web Services', awsSns: 'Amazon Web Services',
  awsSqs: 'Amazon Web Services', awsLambda: 'Amazon Web Services', awsTextract: 'Amazon Web Services',
  awsRekognition: 'Amazon Web Services', awsComprehend: 'Amazon Web Services',
  awsDynamoDb: 'Amazon Web Services', awsTranscribe: 'Amazon Web Services',
  lmOllama: 'Ollama server', lmChatOllama: 'Ollama server', embeddingsOllama: 'Ollama server',
  embeddingsHuggingFaceInference: 'Hugging Face', lmOpenHuggingFaceInference: 'Hugging Face',
  vectorStorePinecone: 'Pinecone', vectorStoreQdrant: 'Qdrant', vectorStoreSupabase: 'Supabase',
  vectorStorePGVector: 'Postgres database', vectorStoreWeaviate: 'Weaviate', vectorStoreMilvus: 'Milvus',
  vectorStoreZep: 'Zep', vectorStoreMongoDBAtlas: 'MongoDB', memoryPostgresChat: 'Postgres database',
  memoryRedisChat: 'Redis database', memoryMongoDbChat: 'MongoDB', memoryZep: 'Zep',
  postgres: 'Postgres database', mySql: 'MySQL database', mongoDb: 'MongoDB', redis: 'Redis database',
  supabase: 'Supabase', slack: 'Slack', slackHitl: 'Slack', discord: 'Discord', telegram: 'Telegram',
  whatsApp: 'Meta (WhatsApp)', facebookGraphApi: 'Meta', stripe: 'Stripe', airtable: 'Airtable',
  notion: 'Notion', hubspot: 'HubSpot', github: 'GitHub', gitlab: 'GitLab', jira: 'Atlassian',
  confluence: 'Atlassian', trello: 'Atlassian', salesforce: 'Salesforce', zendesk: 'Zendesk',
  twilio: 'Twilio', sendGrid: 'Twilio SendGrid', mailchimp: 'Mailchimp', mailgun: 'Mailgun',
  shopify: 'Shopify', wooCommerce: 'WooCommerce store', pipedrive: 'Pipedrive', asana: 'Asana',
  clickUp: 'ClickUp', mondayCom: 'monday.com', typeform: 'Typeform', calendly: 'Calendly',
  zoom: 'Zoom', dropbox: 'Dropbox', box: 'Box', emailSend: 'Email (SMTP server)',
  emailReadImap: 'Email (IMAP server)', ftp: 'FTP server', ssh: 'SSH server',
};

// The company behind a web address, matched on the end of the host name.
const HOSTS = [
  ['openai.com', 'OpenAI'], ['anthropic.com', 'Anthropic'], ['groq.com', 'Groq'],
  ['mistral.ai', 'Mistral AI'], ['googleapis.com', 'Google'], ['google.com', 'Google'],
  ['slack.com', 'Slack'], ['stripe.com', 'Stripe'], ['airtable.com', 'Airtable'],
  ['notion.com', 'Notion'], ['notion.so', 'Notion'], ['hubapi.com', 'HubSpot'],
  ['hubspot.com', 'HubSpot'], ['github.com', 'GitHub'], ['atlassian.net', 'Atlassian'],
  ['atlassian.com', 'Atlassian'], ['microsoft.com', 'Microsoft'], ['microsoftonline.com', 'Microsoft'],
  ['office.com', 'Microsoft'], ['office365.com', 'Microsoft'], ['outlook.com', 'Microsoft'],
  ['azure.com', 'Microsoft'], ['windows.net', 'Microsoft'], ['amazonaws.com', 'Amazon Web Services'],
  ['discord.com', 'Discord'], ['discordapp.com', 'Discord'], ['telegram.org', 'Telegram'],
  ['twilio.com', 'Twilio'], ['sendgrid.com', 'Twilio SendGrid'], ['sendgrid.net', 'Twilio SendGrid'],
  ['mailgun.net', 'Mailgun'], ['salesforce.com', 'Salesforce'], ['zendesk.com', 'Zendesk'],
  ['myshopify.com', 'Shopify'], ['shopify.com', 'Shopify'], ['cohere.com', 'Cohere'],
  ['cohere.ai', 'Cohere'], ['huggingface.co', 'Hugging Face'], ['pinecone.io', 'Pinecone'],
  ['supabase.co', 'Supabase'], ['google', 'Google'], ['europa.eu', 'European Commission'],
  ['n8n.io', 'n8n'],
];

// Nodes whose destination is a web address in their own settings.
const URL_PARAMS = {
  httpRequest: ['url'], toolHttpRequest: ['url'], httpRequestTool: ['url'], graphql: ['endpoint'],
  mcpClientTool: ['endpointUrl', 'sseEndpoint'], mcpClient: ['endpointUrl'], sseTrigger: ['url'],
};
const CALLERS = new Set(['executeWorkflow', 'toolWorkflow', 'retrieverWorkflow']);
const PREFIXES = ['lmChat', 'lm', 'embeddings', 'vectorStore', 'memory', 'tool', 'reranker', 'document'];
const NETWORK = /helpers\.httpRequest|helpers\.request|\bfetch\s*\(|\baxios\b|XMLHttpRequest|\brequests\.(get|post|put|patch|delete)\b|\burllib\b/;

function prettyType(t) {
  let s = String(t).replace(/(Trigger|Tool)$/, '');
  for (const p of PREFIXES) {
    if (s.startsWith(p) && s.length > p.length && /[A-Z]/.test(s[p.length])) { s = s.slice(p.length); break; }
  }
  s = s.replace(/([a-z0-9])([A-Z])/g, '$1 $2');
  return s.charAt(0).toUpperCase() + s.slice(1);
}
function vendorOfType(short) {
  const base = short.replace(/(Trigger|Tool)$/, '');
  return VENDOR[short] || VENDOR[base] || prettyType(short);
}
function vendorOfCredential(ct) {
  const base = String(ct || '').replace(/(OAuth2Api|OAuth2|Api)$/, '');
  return base ? (VENDOR[base] || prettyType(base)) : null;
}
function registrable(h) {
  const parts = h.split('.');
  if (/^\d+(\.\d+){3}$/.test(h) || parts.length < 3) return h;
  const last = parts[parts.length - 1], second = parts[parts.length - 2];
  if (last.length === 2 && ['co', 'com', 'org', 'net', 'gov', 'ac', 'edu'].includes(second)) return parts.slice(-3).join('.');
  return parts.slice(-2).join('.');
}
function vendorOfHost(h, fallback) {
  for (const [d, v] of HOSTS) if (h === d || h.endsWith('.' + d)) return v;
  return fallback || registrable(h);
}
// Literal hosts only. A host that is partly built at run time is NOT returned, so it lands in
// "unresolved" instead of being guessed.
function hostsIn(value) {
  if (typeof value !== 'string') return [];
  const re = /https?:\/\/(localhost|[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+)(?=[:\/?#'"`\s)\]]|$)/gi;
  const out = [];
  let m;
  while ((m = re.exec(value)) !== null) out.push(m[1].toLowerCase());
  return out;
}
// Comments name web pages without calling them, so they are removed before hosts are read.
function stripComments(src, python) {
  let out = '', i = 0, q = null;
  while (i < src.length) {
    const c = src[i], n = src[i + 1];
    if (q) {
      out += c;
      if (c === '\\') { out += n || ''; i += 2; continue; }
      if (c === q) q = null;
      i++; continue;
    }
    if (c === '"' || c === "'" || (!python && c === '`')) { q = c; out += c; i++; continue; }
    if ((python && c === '#') || (!python && c === '/' && n === '/')) {
      while (i < src.length && src[i] !== '\n') i++;
      continue;
    }
    if (!python && c === '/' && n === '*') {
      i += 2;
      while (i < src.length && !(src[i] === '*' && src[i + 1] === '/')) i++;
      i += 2; continue;
    }
    out += c; i++;
  }
  return out;
}

// An address kept in a Set node - the pattern n8n's own template guidelines ask for - is followed
// there: a reference to that node's .json.api_url resolves to what was typed into it. Only a value
// that is itself a full literal address counts; anything else stays unresolved.
const REF = /\$\(\s*['"]([^'"]+)['"]\s*\)\s*\.\s*(?:first\(\)|last\(\)|item|all\(\)\s*\[\s*\d+\s*\])\s*\.\s*json\s*(?:\.\s*([A-Za-z_$][\w$]*)|\[\s*['"]([^'"]+)['"]\s*\])/g;
function setValue(node, field) {
  const p = node.parameters || {};
  for (const a of (p.assignments && p.assignments.assignments) || []) if (a && a.name === field) return a.value;
  for (const kind of Object.keys(p.values || {})) for (const a of p.values[kind] || []) if (a && a.name === field) return a.value;
  if (typeof p.jsonOutput === 'string') {
    try { const j = JSON.parse(p.jsonOutput.replace(/^=/, '')); if (j && typeof j[field] === 'string') return j[field]; } catch (e) { /* not plain JSON */ }
  }
  return undefined;
}
function hostsViaSettings(value, nodes) {
  if (typeof value !== 'string') return [];
  const out = [];
  REF.lastIndex = 0;
  let m;
  while ((m = REF.exec(value)) !== null) {
    const src = (nodes || []).find((x) => x && x.name === m[1] && String(x.type).endsWith('.set') && !x.disabled);
    const v = src ? setValue(src, m[2] || m[3]) : undefined;
    if (typeof v === 'string') out.push(...hostsIn(v));
  }
  return out;
}

function scanNodes(nodes, prefix, acc, depth) {
  for (const n of nodes || []) {
    if (!n || n.disabled) continue;                        // a disabled node sends nothing
    const full = String(n.type || '');
    const short = full.split('.').pop();
    if (short === 'stickyNote') continue;
    const where = prefix + (n.name || short);
    const p = n.parameters || {};

    if (CALLERS.has(short)) {                              // hands its items to another workflow
      const src = p.source || 'database';
      if (src === 'parameter') {
        let inner = null;
        try { inner = typeof p.workflowJson === 'string' ? JSON.parse(p.workflowJson) : p.workflowJson; } catch (e) { inner = null; }
        if (inner && Array.isArray(inner.nodes) && depth < 5) scanNodes(inner.nodes, where + ' > ', acc, depth + 1);
        else acc.unresolved.push({ node: where, why: 'carries an inline sub-workflow that could not be read' });
      } else if (src === 'database') {
        const w = p.workflowId;
        const id = w && typeof w === 'object' ? w.value : w;
        if (id === undefined || id === null || id === '') continue;
        if (String(id).startsWith('=')) acc.unresolved.push({ node: where, why: 'picks the workflow it calls at run time' });
        else acc.calls.push({ id: String(id), kind: 'sub-workflow', node: where });
      } else {
        acc.unresolved.push({ node: where, why: 'loads the workflow it calls from ' + src });
      }
      continue;
    }

    if (URL_PARAMS[short]) {                               // HTTP Request and friends
      const hosts = [];
      let how = 'web address';
      for (const k of URL_PARAMS[short]) hosts.push(...hostsIn(p[k]));
      if (!hosts.length) {
        for (const k of URL_PARAMS[short]) hosts.push(...hostsViaSettings(p[k], nodes));
        if (hosts.length) how = 'web address kept in a Set node';
      }
      // An n8n API credential points at an n8n instance you run, so it is not an outside processor.
      if (p.authentication === 'predefinedCredentialType' && p.nodeCredentialType === 'n8nApi') continue;
      const credVendor = p.authentication === 'predefinedCredentialType' ? vendorOfCredential(p.nodeCredentialType) : null;
      if (hosts.length) for (const h of [...new Set(hosts)]) acc.dests.push({ processor: vendorOfHost(h, credVendor), host: h, node: where, how });
      else if (credVendor) acc.dests.push({ processor: credVendor, host: null, node: where, how: 'credential' });
      else acc.unresolved.push({ node: where, why: 'builds its web address at run time' });
      continue;
    }

    if (short === 'code' || short === 'function' || short === 'functionItem') {
      const python = p.language === 'pythonNative' || p.language === 'python';
      const collect = (v, out) => { if (typeof v === 'string') out.push(v); else if (v && typeof v === 'object') for (const x of Object.values(v)) collect(x, out); return out; };
      const texts = collect([p.jsCode, p.pythonCode, p.functionCode, p.code], []);
      let found = 0, calls = false;
      for (const t of texts) {
        if (typeof t !== 'string' || !t) continue;
        const clean = stripComments(t, python);
        for (const h of new Set(hostsIn(clean))) { acc.dests.push({ processor: vendorOfHost(h), host: h, node: where, how: 'address in code' }); found++; }
        if (NETWORK.test(clean)) calls = true;
      }
      if (!found && calls) acc.unresolved.push({ node: where, why: 'makes network calls to an address built at run time' });
      continue;
    }

    if (short === 'mcpTrigger') { acc.unresolved.push({ node: where, why: 'answers MCP clients; which AI service connects is not in the workflow' }); continue; }
    if (short === 'executeCommand') { acc.unresolved.push({ node: where, why: 'runs a shell command; where that sends data is not in the workflow' }); continue; }
    if (LOCAL.has(short) || LOCAL.has(short.replace(/(Trigger|Tool)$/, '')) || short.startsWith('textSplitter')) continue;

    acc.dests.push({ processor: vendorOfType(short), host: null, node: where, how: 'node' });
  }
}

function scanVersions(list, settings) {
  const acc = { dests: [], unresolved: [], calls: [] };
  for (const nodes of list) scanNodes(nodes, '', acc, 0);
  if (settings && settings.errorWorkflow) acc.calls.push({ id: String(settings.errorWorkflow), kind: 'error workflow', node: 'workflow settings' });
  const key = (o) => JSON.stringify(o);
  const uniq = (a) => [...new Map(a.map((x) => [key(x), x])).values()];
  return { dests: uniq(acc.dests), unresolved: uniq(acc.unresolved), calls: uniq(acc.calls) };
}

const onlyTag = String($('Processor Rules').first().json.only_tag || '').trim().toLowerCase();
const tagsOf = (w) => (w.tags || []).map((t) => (typeof t === 'string' ? t : t && t.name)).filter(Boolean);
const all = $input.all().map((i) => i.json).filter((w) => w && w.id);
const usable = all.filter((w) => !w.isArchived);
// only_tag limits which workflows are JUDGED. Every workflow stays available, so data handed to a
// sub-workflow outside the tag is still followed.
const inScope = (w) => !onlyTag || tagsOf(w).some((t) => t.toLowerCase() === onlyTag);
if (!usable.some(inScope)) {
  return [{ json: { scan_empty: true, workflows_seen: all.length, archived_skipped: all.length - usable.length, only_tag: onlyTag } }];
}

return usable.map((w) => {
  const tags = tagsOf(w);
  const published = w.activeVersion && Array.isArray(w.activeVersion.nodes) ? w.activeVersion.nodes : null;
  const saved = Array.isArray(w.nodes) ? w.nodes : [];
  // What actually runs is the PUBLISHED version when there is one, otherwise the saved one. This
  // holds for a workflow's own trigger and when another workflow calls it: measured 2026-09-25, a
  // live parent calling a sub-workflow whose saved draft differs got the published version back.
  const runs = scanVersions([published || saved], w.settings);
  // A saved draft that is not published yet cannot send anything, but it will once published.
  let draftAdds = [];
  if (published) {
    const pubNames = new Set(runs.dests.map((d) => d.processor));
    draftAdds = [...new Set(scanVersions([saved], null).dests.map((d) => d.processor))].filter((x) => !pubNames.has(x));
  }
  return { json: {
    scan_empty: false,
    in_scope: inScope(w),
    workflow_id: w.id,
    workflow_name: w.name,
    active: w.active === true,
    tags,
    is_self: w.id === selfId,
    judged_version: published ? 'published' : 'saved',
    destinations: runs.dests,
    unresolved: runs.unresolved,
    calls: runs.calls,
    draft_adds: draftAdds,
    workflows_seen: all.length,
    archived_skipped: all.length - usable.length,
  } };
});

// Give every workflow one verdict, following its data into sub-workflows and its error workflow.
//   switch_off - sends data to a blocked processor, or one whose DPA has ended
//                (or to an unknown one, when unknown_means_blocked is on)
//   review     - sends data to a processor nobody approved, or somewhere the scan cannot resolve
//   clean      - every processor it uses has a valid DPA, or it uses none
//   exempt     - tagged by a human as carrying no personal data, or this scanner itself
const rules = $('Processor Rules').first().json;
const rows = $input.all().map((i) => i.json);
const byId = new Map(rows.map((w) => [w.workflow_id, w]));

const today = new Date().toISOString().slice(0, 10);
const warnDays = Math.max(0, Number(rules.dpa_warning_days) || 0);
const soon = new Date(Date.now() + warnDays * 86400000).toISOString().slice(0, 10);
const list = (s) => String(s || '').split(/[,\n]/).map((x) => x.trim()).filter(Boolean);
const lc = (s) => String(s || '').toLowerCase();

const problems = [];
const approved = list(rules.approved_processors).map((entry) => {
  const m = entry.match(/^(.*?)\s+until\s+(\d{4}-\d{2}-\d{2})$/i);
  if (m) return { name: m[1].trim(), until: m[2] };
  if (/\buntil\b/i.test(entry)) problems.push('could not read the date in "' + entry + '" - write it as Name until YYYY-MM-DD. It is treated as not approved.');
  return /\buntil\b/i.test(entry) ? null : { name: entry, until: null };
}).filter(Boolean);
const blocked = list(rules.blocked_processors);
const notProcessors = list(rules.not_a_processor);
for (const a of approved) if (blocked.some((b) => lc(b) === lc(a.name))) problems.push(a.name + ' is on both lists; blocked wins.');

function matches(entry, d) {
  const e = lc(entry);
  if (!e) return false;
  if (lc(d.processor) === e) return true;
  const h = lc(d.host);
  if (!h) return false;
  if (e.startsWith('.')) return h.endsWith(e);
  if (e.endsWith('.')) return h.startsWith(e);
  return h === e || h.endsWith('.' + e);
}
const RANK = { blocked: 5, dpa_ended: 4, unknown: 3, dpa_ending: 2, approved: 1 };
// This instance's own address (from editor_url) is yours: webhooks you call on it are not a processor.
// n8n's Code sandbox has no URL global (measured: "URL is not defined"), so the host is read with a pattern.
const ownHost = ((String(rules.editor_url || '').match(/^[a-z][a-z0-9+.-]*:\/\/([^\/:?#\s]+)/i) || [])[1] || '').toLowerCase();
function statusOf(d) {
  if (notProcessors.some((e) => matches(e, d))) return { status: 'not_a_processor' };
  if (ownHost && d.host && lc(d.host) === ownHost) return { status: 'not_a_processor' };
  if (blocked.some((e) => matches(e, d))) return { status: 'blocked' };
  const a = approved.find((e) => matches(e.name, d));
  if (!a) return { status: 'unknown' };
  if (a.until && a.until < today) return { status: 'dpa_ended', until: a.until };
  if (a.until && a.until <= soon) return { status: 'dpa_ending', until: a.until };
  return { status: 'approved', until: a.until };
}

// Everything this workflow hands data to, directly or through the workflows it calls.
function gather(w, seen, via) {
  const dests = [], unresolved = [];
  const d0 = w.destinations, u0 = w.unresolved, c0 = w.calls;   // the version that runs, root or callee
  for (const d of d0 || []) dests.push(Object.assign({}, d, { node: via + d.node }));
  for (const u of u0 || []) unresolved.push({ node: via + u.node, why: u.why });
  for (const c of c0 || []) {
    const callee = byId.get(c.id);
    const label = c.kind === 'error workflow' ? 'its error workflow' : 'sub-workflow';
    if (!callee) {
      unresolved.push({ node: via + c.node, why: 'hands data to ' + label + ' ' + c.id + ', which this scan cannot see' });
      continue;
    }
    if (seen.has(c.id)) continue;
    seen.add(c.id);
    const sub = gather(callee, seen, via + (c.kind === 'error workflow' ? 'error workflow "' : 'sub-workflow "') + callee.workflow_name + '" > ');
    dests.push(...sub.dests);
    unresolved.push(...sub.unresolved);
  }
  return { dests, unresolved };
}

// Where the data leaves: the first path, and how many more there are.
const via = (p) => ' (via ' + p.via[0] + (p.via.length > 1 ? ' and ' + (p.via.length - 1) + ' more' : '') + ')';
const exemptTag = lc(rules.exempt_tag);
const base = String(rules.editor_url || '').replace(/\/+$/, '');

return rows.filter((w) => w.in_scope).map((w) => {
  const { dests, unresolved } = gather(w, new Set([w.workflow_id]), '');
  const procs = new Map();
  for (const d of dests) {
    const s = statusOf(d);
    if (s.status === 'not_a_processor') continue;
    const p = procs.get(d.processor) || { name: d.processor, status: s.status, until: s.until || null, via: [] };
    if (RANK[s.status] > RANK[p.status]) { p.status = s.status; p.until = s.until || null; }
    const where = d.node + (d.host ? ' (' + d.host + ')' : '');
    if (!p.via.includes(where)) p.via.push(where);
    procs.set(d.processor, p);
  }
  const processors = [...procs.values()];
  const bad = processors.filter((p) => p.status === 'blocked' || p.status === 'dpa_ended');
  const unknown = processors.filter((p) => p.status === 'unknown');
  const exempt = exemptTag !== '' && (w.tags || []).some((t) => lc(t) === exemptTag);

  let verdict, reason;
  if (w.is_self) { verdict = 'exempt'; reason = 'this scanner does not judge itself'; }
  else if (exempt) { verdict = 'exempt'; reason = 'tagged ' + rules.exempt_tag + ' by a person'; }
  else if (bad.length) {
    verdict = 'switch_off';
    reason = bad.map((p) => (p.status === 'blocked' ? p.name + ' is blocked' : 'the DPA with ' + p.name + ' ended ' + p.until) + via(p)).join('; ');
  } else if ((unknown.length || unresolved.length) && rules.unknown_means_blocked === true) {
    verdict = 'switch_off';
    reason = 'sends data to a processor nobody approved, and unknown_means_blocked is on';
  } else if (unknown.length || unresolved.length) {
    verdict = 'review';
    reason = unknown.map((p) => p.name + ' is not on the approved list' + via(p)).concat(unresolved.map((u) => u.node + ' ' + u.why)).join('; ');
  } else {
    verdict = 'clean';
    reason = processors.length ? 'every processor it uses has a valid DPA' : 'sends data to no outside processor';
  }

  return { json: {
    workflow_id: w.workflow_id,
    workflow_name: w.workflow_name,
    active: w.active,
    verdict,
    reason,
    judged_version: w.judged_version,
    processors,
    unresolved,
    dpa_warnings: processors.filter((p) => p.status === 'dpa_ending').map((p) => ({ name: p.name, until: p.until })),
    draft_adds: w.draft_adds || [],
    link: base ? base + '/workflow/' + w.workflow_id : '',
    config_problems: problems,
    outcome: null,
    error_message: null,
  } };
});

// One Slack message for the whole run. Quiet when nothing needs a person, unless
// post_when_clean is on.
const rules = $('Processor Rules').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.workflow_id);
// Only workflows switched off in this run carry an outcome. For the rest it follows from the
// verdict: a switch-off verdict on a workflow that is not live, or while switch_off_blocked is off.
const outcomeOf = (r) => r.outcome || (r.verdict === 'switch_off' ? (r.active ? 'needs_human_switch_off' : 'not_live') : r.verdict);
const pick = (k) => rows.filter((r) => outcomeOf(r) === k);
const off = pick('switched_off');
const unconfirmed = pick('switch_off_unconfirmed');
const failed = pick('switch_off_failed');
const byHand = pick('needs_human_switch_off');
const idle = pick('not_live');
const review = pick('review');
const clean = pick('clean');
const exempt = pick('exempt');
const liveReview = review.filter((r) => r.active);
const idleReview = review.filter((r) => !r.active);

const label = (r) => (r.link ? '<' + r.link + '|' + r.workflow_name + '>' : r.workflow_name + ' (' + r.workflow_id + ')');
const cap = (arr, f, n) => arr.slice(0, n).map(f).concat(arr.length > n ? ['...and ' + (arr.length - n) + ' more'] : []);
const lines = [];
const section = (title, arr, f) => { if (arr.length) { lines.push('', '*' + title + '*'); lines.push(...cap(arr, f, 25)); } };

// DPA end dates coming up, for processors used by live workflows.
const soon = new Map();
for (const r of rows.filter((x) => x.active)) {
  for (const w of r.dpa_warnings || []) {
    const s = soon.get(w.name) || { name: w.name, until: w.until, workflows: [] };
    s.workflows.push(r.workflow_name);
    soon.set(w.name, s);
  }
}
const warnings = [...soon.values()].sort((a, b) => (a.until < b.until ? -1 : 1));
const problems = [...new Set(rows.flatMap((r) => r.config_problems || []))];
const drafts = rows.filter((r) => (r.draft_adds || []).length);

// What live workflows use, by processor.
const inUse = new Map();
for (const r of rows.filter((x) => x.active && outcomeOf(x) !== 'exempt')) {
  for (const p of r.processors || []) {
    const u = inUse.get(p.name) || { name: p.name, status: p.status, count: 0 };
    u.count++;
    inUse.set(p.name, u);
  }
}
const STATUS = { approved: 'DPA valid', dpa_ending: 'DPA ending soon', dpa_ended: 'DPA ended', blocked: 'blocked', unknown: 'not approved' };

const live = rows.filter((r) => r.active).length;
lines.push('*Processor check ' + new Date().toISOString().slice(0, 10) + '*');
lines.push('Judged ' + rows.length + ' workflows (' + live + ' live). Switched off ' + off.length +
  ', need review ' + liveReview.length + ', clean ' + clean.length + ', exempt ' + exempt.length + '.');
section('Switched off', off, (r) => '- ' + label(r) + ': ' + r.reason);
section('Tried to switch off, but it still shows as live', unconfirmed, (r) => '- ' + label(r) + ': ' + r.reason);
section('Could not switch off', failed, (r) => '- ' + label(r) + ': ' + r.reason + '. Error: ' + (r.error_message || 'unknown'));
section('Switch these off by hand (switch_off_blocked is off)', byHand, (r) => '- ' + label(r) + ': ' + r.reason);
section('Live, needs a decision', liveReview, (r) => '- ' + label(r) + ': ' + r.reason);
section('DPA ending within ' + rules.dpa_warning_days + ' days', warnings, (w) => '- ' + w.name + ' until ' + w.until + ', used by ' + w.workflows.length + ' live workflow(s)');
section('Unpublished drafts that add a processor', drafts, (r) => '- ' + label(r) + ' adds ' + r.draft_adds.join(', '));
section('Settings problems in Processor Rules', problems, (p) => '- ' + p);
if (idle.length || idleReview.length) {
  lines.push('', 'Not live: ' + idle.length + ' would be switched off and ' + idleReview.length + ' need review if they are published or called.');
}
if (inUse.size) {
  lines.push('', '*Processors used by live workflows*');
  lines.push([...inUse.values()].sort((a, b) => b.count - a.count).map((u) => u.name + ' (' + (STATUS[u.status] || u.status) + ', ' + u.count + ')').join(', '));
}

const needsPerson = off.length + unconfirmed.length + failed.length + byHand.length + liveReview.length + warnings.length + problems.length + drafts.length;
return [{ json: {
  post: needsPerson > 0 || rules.post_when_clean === true,
  needs_person: needsPerson,
  text: lines.join('\n'),
  counts: { judged: rows.length, live, switched_off: off.length, unconfirmed: unconfirmed.length, failed: failed.length,
            by_hand: byHand.length, not_live: idle.length, review_live: liveReview.length, review_not_live: idleReview.length,
            clean: clean.length, exempt: exempt.length, dpa_warnings: warnings.length, settings_problems: problems.length },
} }];
